import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/dungeon/commands.md","filePath":"en/modules/dungeon/commands.md","lastUpdated":0}`),a={name:`en/modules/dungeon/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h1><p>The main command is <code>/edg</code>; you can also use the aliases <code>/dungeon</code> and <code>/edungeon</code>. Player-side commands are open by default (<code>emakidungeon.play</code> defaults to <code>true</code>), while admin and editor commands require their own permissions</p><h2 id="player-commands" tabindex="-1">Player commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to “Player commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Permission</th></tr></thead><tbody><tr><td><code>/edg help</code></td><td>Show command help (same as running <code>/edg</code> with no arguments)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg list</code></td><td>List the currently available dungeons</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg enter &lt;dungeonId&gt;</code></td><td>Start a challenge and enter the dungeon; in a party <strong>only the leader may start</strong></td><td><code>emakidungeon.play</code> + <code>emakidungeon.dungeon.&lt;dungeonId&gt;</code></td></tr><tr><td><code>/edg leave</code></td><td>Leave the current dungeon; asks for a second confirmation first - type <code>confirm</code> in chat to leave, <code>cancel</code> to stay</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg cancel</code></td><td>Cancel an ongoing entry wait or challenge (any member can cancel during the ready window)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg ready</code></td><td>Confirm readiness during the ready window (the confirmation button works too)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg rewards</code></td><td>Open your personal reward box and claim payouts</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg stats [player] [dungeonId]</code></td><td>Show entry counts (day/week/month and cooldown) plus best results</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg rank &lt;dungeonId&gt;</code></td><td>Show the dungeon&#39;s top 10 leaderboard (score, duration, difficulty, party)</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg globalchat &lt;on|off&gt;</code></td><td>Toggle global chat listening; <code>on</code> bridges chat in and out of the instance, <code>off</code> keeps dungeon chat inside the instance</td><td><code>emakidungeon.play</code></td></tr><tr><td><code>/edg editor &lt;dungeonId&gt;</code></td><td>Open the map editor and enter the dungeon&#39;s dedicated edit world</td><td><code>emakidungeon.editor</code></td></tr></tbody></table><h2 id="party-subcommands" tabindex="-1">Party subcommands <a class="header-anchor" href="#party-subcommands" aria-label="Permalink to “Party subcommands”">​</a></h2><p><code>/edg party &lt;sub&gt;</code> manages your party:</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th><th>Restrictions</th></tr></thead><tbody><tr><td><code>create</code></td><td>Create a new party (you become the leader)</td><td>Cannot create while already in a party</td></tr><tr><td><code>invite &lt;player&gt;</code></td><td>In a party: invite that player (leader only); not in a party: ask to join, handled by the invite mode</td><td>Leader-only when you already have a party</td></tr><tr><td><code>accept</code></td><td>The invitee accepts an invitation; the receiver of an application (the leader) approves it</td><td>Depends on whether you received an invite or an application</td></tr><tr><td><code>deny</code></td><td>Refuse a received invite (invitee) or reject an incoming application (leader)</td><td>Depends on whether you received an invite or an application</td></tr><tr><td><code>kick &lt;player&gt;</code></td><td>Remove a member</td><td>Leader only</td></tr><tr><td><code>leave</code></td><td>Leave the party (the leader hands over to another member first)</td><td>—</td></tr><tr><td><code>disband</code></td><td>Disband the whole party</td><td>Leader only</td></tr><tr><td><code>chat</code></td><td>Toggle the party channel: once on, your messages are visible to party members only</td><td>—</td></tr></tbody></table><p>The invite mode comes from the global <code>party.invite-mode</code> and decides what happens when a player without a party asks to join another: <code>public</code> joins directly, <code>apply</code> files an application waiting for the leader&#39;s approval, <code>invite</code> only lets invited players in (any other value behaves like <code>invite</code>). The party size cap is <code>party.max-size</code></p><h2 id="editor-session-commands" tabindex="-1">Editor session commands <a class="header-anchor" href="#editor-session-commands" aria-label="Permalink to “Editor session commands”">​</a></h2><p>Run <code>/edg editor &lt;dungeonId&gt;</code> with the <code>emakidungeon.editor</code> permission to open an editing session:</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td><code>/edg editor pos1</code> / <code>pos2</code></td><td>Record the first / second corner of a region (stand on each diagonal corner of the target area)</td></tr><tr><td><code>/edg editor mark &lt;type&gt; [id]</code></td><td>Place a marker on the block you are looking at (16 blocks reach); markers are staged in the session and written to <code>flow.yml</code> on save</td></tr><tr><td><code>/edg editor marks</code></td><td>List the markers staged in this session</td></tr><tr><td><code>/edg editor fill &lt;block&gt;</code></td><td>Fill the area circled by <code>pos1</code> + <code>pos2</code> (written in frames, with a size cap)</td></tr><tr><td><code>/edg editor test</code></td><td>Test start: runs the normal entry flow, <strong>counts nothing and never ranks</strong>; refused while unsaved changes exist</td></tr><tr><td><code>/edg editor exit</code></td><td>Leave the session; refused while unsaved changes exist, so save or discard first</td></tr></tbody></table><p>Marker types come in two groups:</p><table tabindex="0"><thead><tr><th>Type</th><th>How</th><th>Purpose</th></tr></thead><tbody><tr><td><code>spawn</code> / <code>option</code> / <code>chest</code></td><td>Single point, aim at a block</td><td>Spawn location / option node / reward point</td></tr><tr><td><code>room</code> / <code>gate</code> / <code>trigger</code></td><td>Region, needs <code>pos1</code> + <code>pos2</code></td><td>Room / gate door area / trigger zone</td></tr></tbody></table><p>The main editor panels (metadata, spawn points and waves, gates, branch options) are edited through GUIs. <strong>Markers and panel edits are only staged; nothing reaches the template files until you click &quot;Save and write back&quot;</strong>, and exiting without saving discards everything. Only one editing session per dungeon template is allowed at a time</p><h2 id="admin-commands" tabindex="-1">Admin commands <a class="header-anchor" href="#admin-commands" aria-label="Permalink to “Admin commands”">​</a></h2><p><code>/edg admin &lt;sub&gt;</code> requires <code>emakidungeon.admin</code> (default OP):</p><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td><code>instances</code></td><td>List running instances (id, dungeon, state, party, write-queue backlog)</td></tr><tr><td><code>stop &lt;instanceId&gt;</code></td><td>Force-stop a specific instance</td></tr><tr><td><code>status</code></td><td>Overview: instance count, live virtual threads, template count, per-pool usage, and write queues</td></tr><tr><td><code>reload</code></td><td>Reload the main configuration and <strong>all dungeon configs</strong>; running instances are untouched, only newly created instances pick up changes</td></tr><tr><td><code>validate</code></td><td>Validate every dungeon template and report missing <code>flow.yml</code> or invalid configurations</td></tr><tr><td><code>poolreset &lt;dungeonId&gt;</code></td><td>Force-reset the pool spare world of a dungeon</td></tr><tr><td><code>clearslots</code></td><td>Clear leftover pool slot reservations</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p><code>reload</code> must be run <strong>in game by a player with the permission</strong>; running it from the console answers with &quot;this command can only be run by a player&quot;. When a bot or script needs to reload, grant that player <code>emakidungeon.admin</code> first</p></div><h2 id="permission-nodes" tabindex="-1">Permission nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to “Permission nodes”">​</a></h2><table tabindex="0"><thead><tr><th>Node</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>emakidungeon.play</code></td><td>All players</td><td>Entering, party, stats, and global listening player commands</td></tr><tr><td><code>emakidungeon.dungeon.*</code></td><td>All players</td><td>Entry to all dungeons (actually checked per <code>emakidungeon.dungeon.&lt;dungeonId&gt;</code>)</td></tr><tr><td><code>emakidungeon.bypass.limit</code></td><td>OP</td><td>Bypass entry counts and cooldowns</td></tr><tr><td><code>emakidungeon.bypass.escape</code></td><td>OP</td><td>Escape-protection exemption (debugging and maintenance)</td></tr><tr><td><code>emakidungeon.script</code></td><td>OP</td><td>Dungeon script loading and trigger registration</td></tr><tr><td><code>emakidungeon.editor</code></td><td>OP</td><td>Map editor sessions</td></tr><tr><td><code>emakidungeon.admin</code></td><td>OP</td><td>Instance management, force stop, reload, pool maintenance</td></tr><tr><td><code>emakidungeon.*</code></td><td>OP</td><td>Wildcard covering everything above</td></tr></tbody></table><p><code>emakidungeon.dungeon.&lt;dungeonId&gt;</code> is <strong>dynamically registered</strong> on startup and reload for every dungeon folder under <code>world/</code>, and defaults to open for all players; deleting the dungeon removes the node. For a members-only dungeon, turn the default off in your permission plugin and grant the node to the right groups</p><h2 id="command-rules-inside-a-dungeon" tabindex="-1">Command rules inside a dungeon <a class="header-anchor" href="#command-rules-inside-a-dungeon" aria-label="Permalink to “Command rules inside a dungeon”">​</a></h2><p>Commands run by players inside an instance pass two gates:</p><ol><li><strong>Escape blacklist</strong> (<code>escape.blacklist</code>, supports <code>*</code> wildcards): a hit is refused immediately with &quot;command restricted in this dungeon (escape blacklist)&quot;, and <strong>no allow-rule can override this layer</strong></li><li><strong>Command guard</strong> (<code>commands.mode</code>, blacklist or whitelist): evaluated against the global <code>commands.rules</code> and the dungeon-level <code>commands.allow</code>, refusing with &quot;command restricted in this dungeon (command guard)&quot;</li></ol><p>Configuration details are on the <a href="./configuration.html">Configuration</a> page</p>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};